import {collectionBonuses,formDefinition} from './form-progress.mjs';
import {ATTRS,CLASSES,ITEMS,PETS} from './data.mjs';
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export const random=s=>{let x=s.rng>>>0;x^=x<<13;x^=x>>>17;x^=x<<5;s.rng=x>>>0;return s.rng/4294967296};
export const roll=(s,low,high)=>Math.floor(random(s)*(high-low+1))+low;
export function dice(s,text){const m=/^(\d+)d(\d+)(?:\+(\d+))?$/.exec(text);if(!m)throw Error('Unsupported dice: '+text);let n=+(m[3]||0);for(let i=0;i<+m[1];i++)n+=roll(s,1,+m[2]);return n}
export const uid=(s,prefix)=>{const id=BigInt(s.nextId);s.nextId=(id+1n).toString();return prefix+id};
export function count(s,id){return s.inventory.stacks[id]||0}
export function addCount(bag,id,n){if(!ITEMS[id]||!Number.isSafeInteger(n))throw Error('Invalid item/quantity');const next=(bag.stacks[id]||0)+n;if(!Number.isSafeInteger(next)||next<0)throw Error('Invalid item balance');if(next)bag.stacks[id]=next;else delete bag.stacks[id]}
export function consume(s,id,n=1){if(count(s,id)<n)return false;addCount(s.inventory,id,-n);return true}
export function gear(s,id){return s.inventory.equipment.find(e=>e.uid===id)}
export function grantGear(s,itemId,plus=0){if(!ITEMS[itemId]?.slot)throw Error('Not equipment');const e={uid:uid(s,'e'),itemId,plus,durability:ITEMS[itemId].durability_max||100,identified:true,cursed:false};s.inventory.equipment.push(e);return e}
const xpCache=[0n,100n];
export function xpNeeded(level){if(!Number.isSafeInteger(level)||level<1)throw Error('Invalid level');for(let l=xpCache.length;l<=level;l++)xpCache[l]=l<=49?100n*BigInt(l)**3n:(xpCache[l-1]*110n+99n)/100n;return xpCache[level]}
export function xpAtLevel(level){let total=0n;for(let l=1;l<level;l++)total+=xpNeeded(l);return total}
export function levelFromXP(total){total=BigInt(total);let l=1,spent=0n;while(spent+xpNeeded(l)<=total){spent+=xpNeeded(l);l++}return l}
export function permanentStats(s){const attrs={...s.player.creationStats};for(const h of s.player.growth)if(h.level<=s.player.level)for(const a in h.allocated||{})if(ATTRS.includes(a))attrs[a]+=h.allocated[a]||0;return attrs}
export function activeEffects(s,actor=s.player){return (actor.effects||[]).filter(e=>e.until>s.clockMs&&(e.started??0)<=s.clockMs)}
export function effectValues(s,actor=s.player){const out={};for(const e of activeEffects(s,actor))for(const [k,v]of Object.entries(e.values||{})){if(typeof v==='number'||typeof v==='boolean')out[k]=(out[k]||0)+Number(v)};return out}
export function applyEffect(s,actor,effect){actor.effects??=[];const old=actor.effects.find(e=>e.group===effect.group);if(old&&old.until>s.clockMs&&(old.strength||0)>(effect.strength||0))return false;actor.effects=actor.effects.filter(e=>e.group!==effect.group);actor.effects.push({...effect,started:s.clockMs,until:s.clockMs+effect.duration*1000});return true}
export function stats(s){const p=s.player,cls=CLASSES[p.classId],attrs=permanentStats(s),permanent={...attrs},bonus={};let maxHp=cls.growth.initial_hp,maxMp=cls.growth.initial_mp;for(const h of p.growth)if(h.level<=p.level){maxHp+=h.hp;maxMp+=h.mp}for(const id of Object.values(s.equipped)){const e=gear(s,id);if(!e)continue;const item=ITEMS[e.itemId];for(const k in item.stats||{})if(typeof item.stats[k]==='number')bonus[k]=(bonus[k]||0)+item.stats[k];if(item.slot!=='weapon'&&item.enchantable)bonus.ac=(bonus.ac||0)-e.plus;if(item.slot!=='weapon'&&e.quality==='blessed'&&['STR','DEX','CON','INT','WIS'].includes(e.blessingStat)){const key=e.blessingStat.toLowerCase();bonus[key]=(bonus[key]||0)+1;}}for(const a of ATTRS)attrs[a]+=bonus[a.toLowerCase()]||0;const capacityCHA=attrs.CHA,fx=effectValues(s),collection=collectionBonuses(s),formSpeed=formDefinition(activeEffects(s).find(e=>e.group==='form')?.formId)?.reward.attackSpeedFactor||1;for(const a of ATTRS)attrs[a]+=fx[a]||0;const weapon=gear(s,s.equipped.weapon),weap=weapon?ITEMS[weapon.itemId]:null;maxHp=Math.floor(maxHp*(fx.maxRatio||1));maxMp=Math.floor(maxMp*(fx.maxRatio||1));return{attrs,permanent,bonus,collection,formSpeed,effects:fx,maxHp,maxMp,ac:10-Math.floor(Math.max(0,attrs.DEX-10)/3)+(bonus.ac||0)+(fx.ac||0),mr:clamp(5*Math.floor(Math.max(0,attrs.WIS-10)/2)+(bonus.mr||0)+(fx.mr||0),0,100),er:(bonus.er||0)+(fx.er||0),sp:Math.floor((attrs.INT-10)/2)+(bonus.sp||0)+(fx.sp||0),resistances:Object.fromEntries(['fire','water','wind','earth'].map(k=>[k,(bonus[k+'_resistance']||0)+(fx[k+'_resistance']||0)])),carry:Math.floor((500+50*attrs.STR+30*attrs.CON)*(1+(bonus.capacity_bonus_percent||0)/100)*(fx.carryMultiplier||1)),petCapacity:Math.floor(capacityCHA/6)+(p.classId==='elf'?2:0),weapon,weap,range:Math.min(weap?.range_cells||1,fx.visionRadius||Infinity),attackInterval:(weap?.attack_interval_ms||1000)/(fx.haste||1)/(fx.brave||1)/formSpeed,moveInterval:400/(fx.haste||1)/(fx.brave||1)/(fx.moveBoost||1),hit:(bonus.hit_bonus||0)+(fx.hit||0)+Math.floor((weapon?.plus||0)/2)+collection.hit,damage:(bonus.damage_bonus||0)+(fx.damage||0)+(weapon?.plus||0)+collection.damage,regenHp:1+Math.max(0,Math.floor((permanent.CON-10)/3))+(p.classId==='knight'?2:0)+(bonus.hp_regen||0)+(fx.hpr||0),regenMp:Math.max(0,Math.floor((permanent.WIS-8)/4))+(p.classId==='mage'?2:0)+(bonus.mp_regen||0)+(fx.mpr||0)} }
export function weight(s,st=stats(s)){let tenth=0;for(const e of s.inventory.equipment)tenth+=Math.round((ITEMS[e.itemId]?.weight||0)*10);for(const e of s.inventory.scrolls||[])tenth+=Math.round((ITEMS[e.itemId]?.weight||0)*10);for(const[id,n]of Object.entries(s.inventory.stacks))tenth+=Math.round((ITEMS[id]?.weight||0)*10)*n;for(const p of s.pets)if(p.collarInBag!==false)tenth+=Math.round((ITEMS['ITEM-PET-COLLAR']?.weight||0)*10);const total=tenth/10,ratio=total/st.carry;return{total,capacity:st.carry,ratio,regenMultiplier:ratio>=.5?0:1,moveMultiplier:ratio>=1?Infinity:ratio>=.8?1.25:1,canAct:ratio<1}}
export function addXP(s,n){const p=s.player;p.totalXP=(BigInt(p.totalXP)+BigInt(n)).toString();const next=levelFromXP(p.totalXP);for(let level=p.level+1;level<=next;level++)if(!p.growth.some(h=>h.level===level)){const a=permanentStats(s),g=CLASSES[p.classId].growth;p.growth.push({level,hp:g.hp_per_level_base+Math.max(0,Math.floor((a.CON-10)/2)),mp:g.mp_per_level_base+Math.max(0,Math.floor((a.WIS-10)/3)),allocated:{}});p.level=level}p.level=next;releasePetExperience(s);const st=stats(s);p.hp=Math.min(p.hp,st.maxHp);p.mp=Math.min(p.mp,st.maxMp)}
export function releasePetExperience(s){for(const pet of s.pets)while(pet.level<s.player.level&&BigInt(pet.xp)>=50n*BigInt(pet.level)**3n){pet.xp=(BigInt(pet.xp)-50n*BigInt(pet.level)**3n).toString();pet.level++}}
export function availablePoints(s){return s.player.growth.filter(h=>h.level>=51&&h.level<=s.player.level).reduce((n,h)=>n+1-Object.values(h.allocated).reduce((a,b)=>a+b,0),0)}
export function resumePetTimers(pet,now){pet.path=[];pet.targetId=null;pet.pathGoal=null;pet.foodAt=now+60000;pet.mpRegenAt=now+8000;pet.effects=(pet.effects||[]).filter(e=>e.until>now);for(const e of pet.effects)if(Number.isFinite(e.tickAt)&&e.tickEvery>0&&e.tickAt<=now)e.tickAt+=(Math.floor((now-e.tickAt)/e.tickEvery)+1)*e.tickEvery}
export function petStats(p){const t=PETS[p.type],a=p.aptitudes;return{maxHp:Math.max(1,Math.floor((t.stats.level1_hp+(p.level-1)*t.growth.hp_per_level)*a.hp/100)),maxMp:t.stats.level1_mp+(p.level-1)*(t.growth.mp_per_level||0),attack:Math.max(1,Math.floor((t.stats.base_attack+.5*(p.level-1))*a.attack/100)),ac:8-Math.floor((a.defense-100)/10)-Math.floor((p.level-1)/5),mr:t.stats.mr,attackInterval:Math.max(1,Math.round(t.stats.attack_interval_seconds*1000*100/a.speed)),moveInterval:Math.max(1,Math.round(t.stats.move_cell_seconds*1000*100/a.speed)),range:t.stats.range_cells}}
export function physicalChance(attacker,defender,{ranged=false}={}){return clamp(70+2*(attacker.level-defender.level)+Math.floor(((attacker.attrs?.[ranged?'DEX':'STR']??10)-10)/2)+(attacker.hit||0)+defender.ac*.5-(ranged?defender.er||0:defender.evasion||0),5,95)/100}
export function magicDamage(base,attacker,defender,element){let damage=(base+2*(attacker.sp||0))*(1-clamp(defender.mr||0,0,100)/200);if(element)damage*=1-clamp(defender.resistances?.[element]||0,-50,80)/100;return Math.max(1,Math.floor(Math.max(0,damage-(defender.reduction||0))*(defender.finalReduction||1)))}
export function statusChance(attacker,defender){return clamp(.55+.02*(attacker.level-defender.level)+.01*((attacker.attrs?.INT??10)-15)-(defender.mr||0)/200,.05,.9)}
export const fusionChance=plus=>Math.max(500,10000-800*plus)/10000;
